class Node {
  int val;
  Node next;

  Node(int x) {
    val = x;
    next = null;
  }
}

class Merge {
  public Node solve(Node head1, Node head2) {
    Node dummy = new Node(0);
    Node cur = dummy;

    Node p1 = head1;
    Node p2 = head2;
    while (p1 != null && p2 != null) {
      cur.next = p1;
      cur = cur.next;
      p1 = p1.next;

      cur.next = p2;
      p2 = p2.next;
      cur = cur.next;
    }

    if (p1 != null) {
      cur.next = p1;
    } else {
      cur.next = p2;
    }

    return dummy.next;
  }
}

